 void UI(Action a){if(!closing&&!IsDisposed)try{BeginInvoke(a);}catch(InvalidOperationException){}}
 void SetState(string text){lock(gate)state=text;UI(()=>status.Text=text);}
 void FilterContracts(){
  if(subscribed)return;
  string previous=contracts.SelectedItem==null?null:contracts.SelectedItem.ToString();
  string query=search.Text.Trim();contracts.BeginUpdate();contracts.Items.Clear();
  foreach(string item in allContracts){string key=item.Substring(item.IndexOf(" | ")+3);if(singleOnly.Checked&&key.Contains("/"))continue;if(query.Length>0&&key.IndexOf(query,StringComparison.OrdinalIgnoreCase)<0)continue;contracts.Items.Add(item);}
  if(previous!=null&&contracts.Items.Contains(previous))contracts.SelectedItem=previous;else if(contracts.Items.Count>0)contracts.SelectedIndex=0;
  contracts.EndUpdate();subscribe.Enabled=authenticated&&contracts.Items.Count>0;
  results.Text=!contractsReady?"登入後可搜尋，例如 TXF、TXFJ6 或 TXX":contracts.Items.Count==0?"沒有符合的商品；此清單沒有找到您輸入的代碼。":"找到 "+contracts.Items.Count+" 個商品；請確認月份後選取，近月連續尚未提供。";
 }
 void Login(){if(attempted){Application.Restart();return;}int p;if(string.IsNullOrWhiteSpace(host.Text)||!int.TryParse(port.Text,out p)||p<1||p>65535||string.IsNullOrWhiteSpace(user.Text)||password.Text.Length==0){MessageBox.Show("請填入兆豐提供的行情主機、連接埠、帳號與密碼。");return;}
  attempted=true;login.Text="重新啟動連線";login.Enabled=false;
  string loginHost=host.Text.Trim(), loginUser=user.Text.Trim(), loginPassword=password.Text;
  host.Enabled=port.Enabled=user.Enabled=password.Enabled=false;
  SetState("正在連接兆豐行情主機，等待登入回覆…");
  loginTimer=new System.Windows.Forms.Timer();loginTimer.Interval=20000;
  loginTimer.Tick+=(sender,args)=>{loginTimer.Stop();if(!contractsReady){SetState("尚未完成連線。可稍候，或按重新啟動；請核對行情 IP、Port 與權限。");login.Enabled=true;}};loginTimer.Start();
  try{api=new spdQuoteAPI();
   api.evOnConnected=new OnQuoteConnected(()=>SetState("主機已連接，等待登入確認"));
   api.evOnDisconnected=new OnQuoteDisconnected(()=>{authenticated=false;SetState("已斷線：畫面保留最後資料，請關閉程式後重新登入");UI(()=>{subscribe.Enabled=false;login.Enabled=true;if(loginTimer!=null)loginTimer.Stop();});});
   api.evOnLogonResponse=new OnQuoteLogonResponse((ok,msg)=>{authenticated=ok;SetState(ok?"登入成功，等待商品清單":"登入遭拒。請核對行情帳密與 API 權限，再按重新啟動。");UI(()=>{if(ok){subscribe.Enabled=contractsReady&&contracts.Items.Count>0;optionSeries.Enabled=false;}else{login.Enabled=true;loginTimer.Stop();}});});
   api.evOnContractDownloadComplete=new OnQuoteContractDownloadComplete(n=>UI(CatalogReady));
   api.evOnTrade=new OnQuoteTrade(Trade);
   api.evOnOrderBook=new OnQuoteOrderBook(Book);
   StartServer();
   SetState("本機看盤已啟動（Port "+localPort+"），正在等待行情登入回覆…");
   password.Clear();
   var connection=new Thread(()=>{try{api.Logon(loginHost,p,loginUser,loginPassword,true);}catch(Exception ex){SetState("連線失敗："+ex.GetType().Name+"。可按重新啟動再試。");UI(()=>{loginTimer.Stop();login.Enabled=true;});}finally{loginPassword=null;}});connection.IsBackground=true;connection.Start();
  }catch(SocketException ex){loginTimer.Stop();login.Enabled=true;loginPassword=null;SetState("本機看盤服務啟動失敗："+ex.SocketErrorCode+"。請關閉舊工具後按重新啟動。");}
  catch(Exception ex){loginTimer.Stop();login.Enabled=true;loginPassword=null;SetState("無法啟動："+ex.GetType().Name+"。請確認官方套件與設定檔齊全，再按重新啟動。");}
 }

 void InitializeHistory(){SetState("正在讀取本機歷史，完成後可登入…");var thread=new Thread(()=>{try{archiveRoot=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"TanyaSiteMarketHistory");Directory.CreateDirectory(archiveRoot);historyLock=new FileStream(Path.Combine(archiveRoot,"connector.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);archive=new MarketArchive(archiveRoot);daily=new TaifexDailyStore(archiveRoot);archiveTimer=new System.Threading.Timer(_=>{if(!closing){archive.Flush();RefreshHistory();UI(CheckRollover);}},null,60000,60000);SetState("歷史保存已啟用；請登入行情");}catch(Exception ex){archive=null;daily=null;if(historyLock!=null){historyLock.Dispose();historyLock=null;}SetState("歷史初始化失敗："+ex.GetType().Name+"；可登入但未保存資料");}UI(()=>login.Enabled=true);});thread.IsBackground=true;thread.Start();}
 void CatalogReady(){contractsReady=true;if(loginTimer!=null)loginTimer.Stop();allContracts.Clear();foreach(var key in api.Futures.Keys)allContracts.Add("期貨 | "+key);foreach(var key in api.Options.Keys)allContracts.Add("選擇權 | "+key);allContracts.Sort(StringComparer.OrdinalIgnoreCase);optionCatalog.Clear();monthlyCatalog.Clear();var now=DateTime.UtcNow.AddHours(8);foreach(var pair in api.Futures){var c=MonthlyContract.Parse(pair.Key,pair.Value.MaturityDate,now);if(c!=null)monthlyCatalog.Add(c);}foreach(var pair in api.Options){var c=pair.Value;var d=OptionDescriptor.Parse(pair.Key,c.MaturityDate,c.StrikePx,c.CallPut,c.ContractMultiplier);if(d!=null&&d.Prefix=="TXO")optionCatalog.Add(d);}if(!subscribed)AutoContracts();login.Enabled=true;SetState(authenticated?(currentMonth.Length>0?"登入成功。已選當前月份大台與月選，訂閱後同時監看小台及微台。":"登入成功，但沒有可交易的當前月份大台，請確認月份規則。"):"商品清單已下載，等待登入確認。");}
 void AutoContracts(){var main=MonthlyContract.Choose(monthlyCatalog,DateTime.UtcNow.AddHours(8),monthRule.SelectedIndex==0);search.Text="TXF";FilterContracts();optionSeries.Items.Clear();if(main==null){currentMonth="";chosenOptionGroup="";contracts.SelectedIndex=-1;subscribe.Enabled=false;SetState("沒有可交易的當月／近月大台，請確認月份規則與行情權限。");return;}contracts.Items.Clear();contracts.Items.Add("期貨 | "+main.Symbol);contracts.SelectedIndex=0;contracts.Enabled=false;search.Enabled=false;singleOnly.Enabled=false;results.Text="自動選擇 "+main.Month+"；大小微台與月選使用同月份。";currentMonth=main.Month;chosenOptionGroup="TXO · "+main.Month.Substring(0,4)+"-"+main.Month.Substring(4,2);if(optionCatalog.Any(c=>MonthlyContract.MonthFor(c.Symbol,DateTime.UtcNow.AddHours(8))==currentMonth)){optionSeries.Items.Add(chosenOptionGroup);optionSeries.SelectedIndex=0;}optionSeries.Enabled=false;subscribe.Enabled=authenticated;}
 void Subscribe(){if(!authenticated||subscribed)return;AutoContracts();if(contracts.SelectedItem==null)return;string key=contracts.SelectedItem.ToString().Split(new[]{" | "},StringSplitOptions.None)[1];optionPlanQueued=false;lock(gate){symbol=key;bars.Clear();trades.Clear();futureFeeds.Clear();lastReceipt=0;quoteReceipt=0;bid=0;ask=0;if(archive!=null)foreach(var m in archive.Recent(symbol,600))bars.Add(new Candle(){time=m.time,open=m.open,high=m.high,low=m.low,close=m.close,volume=m.volume});foreach(string prefix in new[]{"TXF","MXF","TMF"}){string code=MonthlyContract.SymbolFor(prefix,currentMonth);futureFeeds[code]=new FutureFeed(){symbol=code,name=prefix=="TXF"?"大台":prefix=="MXF"?"小台":"微台",multiplier=prefix=="TXF"?200:prefix=="MXF"?50:10};}}try{foreach(var f in futureFeeds.Values){if(!api.Futures.ContainsKey(f.symbol)){f.error="SDK 商品清單沒有此合約";continue;}var c=api.Futures[f.symbol];if(c.ContractMultiplier>0&&!double.IsInfinity(c.ContractMultiplier)&&!double.IsNaN(c.ContractMultiplier))f.multiplier=c.ContractMultiplier;f.accepted=api.SubscribeContract(c);if(!f.accepted)f.error="API 未接受訂閱";}if(!futureFeeds[symbol].accepted){api.UnsubscribeAll();SetState("大台訂閱未成功，請確認行情權限與商品。");return;}subscribed=true;subscribe.Enabled=false;contracts.Enabled=false;search.Enabled=false;singleOnly.Enabled=false;monthRule.Enabled=false;view.Enabled=true;phone.Enabled=true;historyDownload.Enabled=historyImport.Enabled=archive!=null&&daily!=null;SetState("大小微台訂閱已送出；收到大台價格後訂閱同月份月選。");RefreshHistory();}catch(Exception ex){SetState("訂閱失敗："+ex.GetType().Name);}}
 void QueueOptions(double reference){if(chosenOptionGroup.Length==0||reference<=0)return;lock(gate){if(optionPlanQueued)return;optionPlanQueued=true;}UI(()=>{if(!subscribed)return;int futures=futureFeeds.Values.Count(f=>f.accepted);int pairs=Math.Max(0,(20-futures)/2);var plan=OptionChain.Select(optionCatalog.Where(c=>MonthlyContract.MonthFor(c.Symbol,DateTime.UtcNow.AddHours(8))==currentMonth),reference,pairs);optionChain.Plan(chosenOptionGroup,plan);foreach(var c in plan){bool accepted=false;try{accepted=api.SubscribeContract(api.Options[c.Symbol]);}catch(Exception){}optionChain.Subscription(c.Symbol,accepted);}RefreshHistory();});}
 void Book(string exchange,string code,string time,MsgOrderBook book){if(closing)return;code=(code??"").Trim();if(book.IsTestMatch||double.IsNaN(book.BidPrice1)||double.IsInfinity(book.BidPrice1)||double.IsNaN(book.AskPrice1)||double.IsInfinity(book.AskPrice1))return;long receipt=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();if(optionChain.Book(code,book.BidPrice1,book.AskPrice1,book.BidQty1,book.AskQty1,receipt)){if(archive!=null)archive.Quote(code,optionChain.Kind(code),optionChain.Strike(code),book.BidPrice1,book.AskPrice1,receipt);}lock(gate){bookCallbacks++;FutureFeed f;if(!futureFeeds.TryGetValue(code,out f))return;f.bid=book.BidPrice1;f.ask=book.AskPrice1;f.quoteReceipt=receipt;if(archive!=null)archive.Quote(code,"future",0,f.bid,f.ask,receipt);if(code!=symbol)return;bid=f.bid;ask=f.ask;quoteReceipt=receipt;if(lastReceipt==0)state="已收到真實報價，等待成交";}if(book.BidPrice1>0&&book.AskPrice1>0)QueueOptions((book.BidPrice1+book.AskPrice1)/2);}
 void AddTrade(string code,string kind,double strike,double price,int qty,string side,long receipt,double multiplier){decimal? premium=kind!="future"&&multiplier>0?(decimal?)((decimal)price*(decimal)multiplier*qty):null;var t=new TradeRecord(){seq=++tradeSeq,receipt=receipt,price=price,qty=qty,side=side,symbol=code,kind=kind,multiplier=multiplier,premiumAmount=premium};trades.Add(t);if(trades.Count>500)trades.RemoveAt(0);if(archive!=null)archive.Trade(code,kind,strike,price,qty,side,receipt,multiplier,feedId,t.seq);}
 void Trade(string exchange,string code,string time,double price,int qty,bool test){if(closing)return;code=(code??"").Trim();lock(gate){tradeCallbacks++;lastTradeSymbol=code;if(test)testTrades++;if(code==symbol)selectedTrades++;}if(test||price<=0||double.IsNaN(price)||double.IsInfinity(price)||qty<=0)return;long receipt=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();lock(gate){if(optionChain.Trade(code,price,qty,receipt)){AddTrade(code,optionChain.Kind(code),optionChain.Strike(code),price,qty,optionChain.Aggressor(code,price,receipt),receipt,optionChain.Multiplier(code));return;}FutureFeed f;if(!futureFeeds.TryGetValue(code,out f))return;string side="unknown";if(f.quoteReceipt>0&&receipt>=f.quoteReceipt&&receipt-f.quoteReceipt<=3000&&f.bid>0&&f.ask>f.bid)side=price>=f.ask?"buy":price<=f.bid?"sell":"unknown";f.last=price;f.lastReceipt=receipt;AddTrade(code,"future",0,price,qty,side,receipt,f.multiplier);if(code!=symbol)return;long minute=receipt/60000*60000;Candle c;if(bars.Count==0||bars[bars.Count-1].time!=minute){c=new Candle(){time=minute,open=price,high=price,low=price,close=price};bars.Add(c);if(bars.Count>600)bars.RemoveAt(0);}else c=bars[bars.Count-1];c.high=Math.Max(c.high,price);c.low=Math.Min(c.low,price);c.close=price;c.volume+=qty;lastReceipt=receipt;matchTime=time;state="已接收真實成交";}QueueOptions(price);UI(()=>last.Text="商品 "+code+" ｜成交 "+price+" ｜單筆 "+qty+" ｜時間 "+time);}
 void RefreshHistory(){if(archive==null)return;string main,month;lock(gate){main=symbol;month=currentMonth;}var summary=archive.Summary(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),main);summary.weekly=summary.weekly.Where(a=>MonthlyContract.MonthFor(a.symbol,DateTime.UtcNow.AddHours(8))==month).ToList();cachedHistory=MarketJson.Write(summary);}
 void RestoreBars(){lock(gate){bars.Clear();foreach(var m in archive.Recent(symbol,600))bars.Add(new Candle(){time=m.time,open=m.open,high=m.high,low=m.low,close=m.close,volume=m.volume});}}
 void CheckRollover(){if(!authenticated||!subscribed||closing)return;var main=MonthlyContract.Choose(monthlyCatalog,DateTime.UtcNow.AddHours(8),monthRule.SelectedIndex==0);if(main==null){SetState("日曆當月已到期；保留原資料，請切換近月規則後重新啟動。");return;}if(main.Month==currentMonth)return;try{api.UnsubscribeAll();lock(gate){subscribed=false;optionPlanQueued=false;optionChain.Plan("",new List<OptionDescriptor>());}Subscribe();if(subscribed)SetState("結算月份已更換，等待新月份行情；歷史分月保存。");}catch(Exception ex){SetState("換月未完成："+ex.GetType().Name+"，請重新啟動工具。");}}
 void DownloadHistory(){if(historyBusy||archive==null||daily==null)return;historyBusy=true;string downloadMonth=currentMonth;historyDownload.Enabled=historyImport.Enabled=false;var thread=new Thread(()=>{try{SetState("歷史回補進行中，即時行情繼續接收…");daily.Download(DateTime.UtcNow.AddHours(8));ticks.Download(DateTime.UtcNow.AddHours(8),downloadMonth,archive);RefreshHistory();RestoreBars();SetState("歷史回補已結束，請在週資料頁確認公布日期與缺口。");}catch(Exception ex){SetState("回補未完成："+ex.GetType().Name+"；可手動匯入官方資料");}finally{historyBusy=false;UI(()=>historyDownload.Enabled=historyImport.Enabled=true);}});thread.IsBackground=true;thread.Start();}
 void ImportHistory(){if(historyBusy||archive==null||daily==null)return;using(var dialog=new OpenFileDialog()){dialog.Filter="期交所 CSV 或 ZIP|*.csv;*.zip";if(dialog.ShowDialog()!=DialogResult.OK)return;string file=dialog.FileName,importMonth=currentMonth;historyBusy=true;historyDownload.Enabled=historyImport.Enabled=false;var thread=new Thread(()=>{try{if(file.EndsWith(".csv",StringComparison.OrdinalIgnoreCase)){string text=MarketCsv.Decode(File.ReadAllBytes(file));var h=MarketCsv.Headers(text.Split(new[]{'\n'},2)[0]);if(MarketCsv.Index(h,"未沖銷契約數","未平倉量")>=0)daily.Import(text,"手動匯入期交所格式 CSV");else ticks.Import(file,importMonth,archive,"手動匯入逐筆 CSV（成交日期／時間）");}else ticks.Import(file,importMonth,archive,"手動匯入逐筆 ZIP（成交日期／時間）");RefreshHistory();RestoreBars();SetState("匯入完成，請查看來源日期與資料涵蓋範圍。");}catch(Exception ex){SetState("匯入失敗："+ex.Message);}finally{historyBusy=false;UI(()=>historyDownload.Enabled=historyImport.Enabled=true);}});thread.IsBackground=true;thread.Start();}}
 string HistoryResponse(string target){var match=Regex.Match(target,@"^/api/history(?:\?date=([0-9]{4}-[0-9]{2}-[0-9]{2})&symbol=([A-Z0-9]+)&session=(all|day|night))?$");if(!match.Success)return "{\"error\":\"歷史查詢參數不符\"}";string date=match.Groups[1].Success?match.Groups[1].Value:DateTime.UtcNow.AddHours(8).ToString("yyyy-MM-dd"),code=match.Groups[2].Success?match.Groups[2].Value:symbol,period=match.Groups[3].Success?match.Groups[3].Value:"all";var result=new ArchiveHistory(){date=date,symbol=code,session=period,minutes=archive==null?new List<ArchiveMinute>():archive.History(code,date,period)};string json=MarketJson.Write(result);var oi=daily==null?new List<OpenInterestWeek>():daily.Week(currentMonth,DateTime.UtcNow.AddHours(8));var ranges=daily==null?new List<ArchiveSession>():daily.Ranges(code);return json.Substring(0,json.Length-1)+",\"openInterest\":"+MarketJson.Write(oi)+",\"officialRanges\":"+MarketJson.Write(ranges)+",\"dailyRecords\":"+MarketJson.Write(daily==null?new List<DailyRecord>():daily.Records(currentMonth))+",\"largeTrades\":"+MarketJson.Write(archive==null?new List<ArchiveBigTrade>():archive.BigHistory(code,date,period,2000))+"}";}

 static string Escape(string s){var b=new StringBuilder();foreach(char c in s){if(c=='"'||c=='\\')b.Append('\\').Append(c);else if(c<32)b.Append("\\u").Append(((int)c).ToString("x4"));else b.Append(c);}return b.ToString();}
 string Snapshot(){lock(gate){var b=new StringBuilder();b.Append("{\"status\":\"").Append(Escape(state)).Append("\",\"symbol\":\"").Append(Escape(symbol)).Append("\",\"connected\":").Append(authenticated?"true":"false").Append(",\"lastReceipt\":").Append(lastReceipt).Append(",\"quoteReceipt\":").Append(quoteReceipt).Append(",\"bid\":").Append(bid.ToString(CultureInfo.InvariantCulture)).Append(",\"ask\":").Append(ask.ToString(CultureInfo.InvariantCulture)).Append(",\"tradeCallbacks\":").Append(tradeCallbacks).Append(",\"selectedTrades\":").Append(selectedTrades).Append(",\"testTrades\":").Append(testTrades).Append(",\"bookCallbacks\":").Append(bookCallbacks).Append(",\"lastTradeSymbol\":\"").Append(Escape(lastTradeSymbol)).Append("\"").Append(",\"matchTime\":\"").Append(Escape(matchTime)).Append("\",\"candles\":[");for(int i=0;i<bars.Count;i++){if(i>0)b.Append(',');var c=bars[i];b.Append("{\"time\":").Append(c.time).Append(",\"open\":").Append(c.open.ToString(CultureInfo.InvariantCulture)).Append(",\"high\":").Append(c.high.ToString(CultureInfo.InvariantCulture)).Append(",\"low\":").Append(c.low.ToString(CultureInfo.InvariantCulture)).Append(",\"close\":").Append(c.close.ToString(CultureInfo.InvariantCulture)).Append(",\"volume\":").Append(c.volume).Append('}');}b.Append("],\"feedId\":\"").Append(feedId).Append("\",\"tradeSeq\":").Append(tradeSeq).Append(",\"trades\":[");for(int i=0;i<trades.Count;i++){if(i>0)b.Append(',');var t=trades[i];b.Append("{\"seq\":").Append(t.seq).Append(",\"receipt\":").Append(t.receipt).Append(",\"price\":").Append(t.price.ToString(CultureInfo.InvariantCulture)).Append(",\"qty\":").Append(t.qty).Append(",\"side\":\"").Append(t.side).Append("\",\"symbol\":\"").Append(Escape(t.symbol??symbol)).Append("\",\"kind\":\"").Append(t.kind??"unknown").Append("\",\"multiplier\":").Append(t.multiplier.ToString(CultureInfo.InvariantCulture)).Append(",\"premiumAmount\":").Append(t.premiumAmount.HasValue?t.premiumAmount.Value.ToString(CultureInfo.InvariantCulture):"null").Append("}");}return b.Append("],\"optionChain\":").Append(optionChain.Json()).Append(",\"historySummary\":").Append(cachedHistory).Append(",\"dailyStatus\":\"").Append(Escape(daily==null?"未初始化":daily.Status)).Append("\",\"tickStatus\":\"").Append(Escape(ticks.Status)).Append("\",\"futureFeeds\":").Append(FutureJson()).Append(",\"alertTrades\":").Append(MarketJson.Write(archive==null?new List<ArchiveBigTrade>():archive.Big(feedId,300))).Append("}").ToString();}}
 string FutureJson(){return "["+string.Join(",",futureFeeds.Values.Select(f=>"{\"symbol\":\""+Escape(f.symbol)+"\",\"name\":\""+f.name+"\",\"last\":"+f.last.ToString(CultureInfo.InvariantCulture)+",\"lastReceipt\":"+f.lastReceipt+",\"error\":\""+Escape(f.error)+"\"}"))+ "]";}
 string PhoneSnapshot(){lock(phoneGate){long expiration=mobileServer==null?0:new DateTimeOffset(mobileServer.Expires).ToUnixTimeMilliseconds();return "{\"state\":\""+Escape(phoneState)+"\",\"url\":\""+Escape(phoneUrl)+"\",\"expires\":"+expiration+"}";}}
 void PhoneState(string text){lock(phoneGate)phoneState=text;UI(()=>phone.Text=phoneUrl.Length>0?"4. 手機配對 QR Code":"4. 手機外網同步");}
 void OpenPhonePage(){UI(()=>Process.Start("http://127.0.0.1:"+localPort+"/phone"));}
 static string FindCloudflared(){var candidates=new List<string>();string local=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);candidates.Add(Path.Combine(local,"Microsoft","WinGet","Links","cloudflared.exe"));string packages=Path.Combine(local,"Microsoft","WinGet","Packages");if(Directory.Exists(packages))foreach(string folder in Directory.GetDirectories(packages,"Cloudflare.cloudflared*"))foreach(string file in Directory.GetFiles(folder,"cloudflared.exe",SearchOption.AllDirectories))candidates.Add(file);string paths=Environment.GetEnvironmentVariable("PATH")??"";foreach(string folder in paths.Split(';')){if(folder.Length>0)try{candidates.Add(Path.Combine(folder.Trim('"'),"cloudflared.exe"));}catch(ArgumentException){}}foreach(string path in candidates)if(File.Exists(path))return path;return null;}
 bool TunnelAlive(){try{return tunnelProcess!=null&&!tunnelProcess.HasExited;}catch(InvalidOperationException){return false;}}
 void StartPhone(){if(phoneStarting)return;if(TunnelAlive()){OpenPhonePage();return;}phoneStarting=true;phone.Enabled=false;PhoneState("正在啟動 HTTPS 手機通道，首次可能需安裝 Cloudflare 工具…");
  var thread=new Thread(()=>{try{
   if(mobileServer!=null)mobileServer.Dispose();mobileServer=new MobileServer(Snapshot,Path.GetFullPath(".."),HistoryResponse);mobileServer.Start();lock(phoneGate)phoneUrl="";OpenPhonePage();
   string executable=FindCloudflared();if(executable==null){PhoneState("首次安裝 Cloudflare 工具，請查看安裝視窗。套件由 winget 驗證。");string script=Path.GetFullPath("Install-Tunnel.ps1");var installer=Process.Start(new ProcessStartInfo("powershell.exe","-NoProfile -ExecutionPolicy Bypass -File \""+script+"\""){UseShellExecute=true});installer.WaitForExit();if(installer.ExitCode!=0)throw new InvalidOperationException("Cloudflare 安裝未完成。請檢查安裝視窗，必要時更新 Microsoft App Installer。");executable=FindCloudflared();if(executable==null)throw new InvalidOperationException("找不到 cloudflared.exe；請重新啟動工具後再試。");}
   if(closing){mobileServer.Dispose();return;}PhoneState("正在建立臨時 HTTPS 通道，請稍候…");var process=new Process();process.StartInfo=new ProcessStartInfo(executable,"tunnel --no-autoupdate --url http://127.0.0.1:"+mobileServer.Port){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true};process.OutputDataReceived+=(sender,args)=>TunnelLine(args.Data);process.ErrorDataReceived+=(sender,args)=>TunnelLine(args.Data);process.EnableRaisingEvents=true;process.Exited+=(sender,args)=>{lock(phoneGate){phoneUrl="";phoneState="手機通道已關閉。請在電腦重新按手機外網同步。";}UI(()=>{phoneStarting=false;phone.Enabled=true;phone.Text="4. 手機外網同步";});};tunnelProcess=process;if(!process.Start())throw new IOException("無法啟動 Cloudflare 通道。");process.BeginOutputReadLine();process.BeginErrorReadLine();
  }catch(Exception ex){if(mobileServer!=null)mobileServer.Dispose();lock(phoneGate){phoneUrl="";phoneState="手機通道啟動失敗："+(ex is InvalidOperationException?ex.Message:ex.GetType().Name)+"。本機行情仍可使用。";}UI(()=>{phoneStarting=false;phone.Enabled=true;});}});thread.IsBackground=true;thread.Start();
 }
 void TunnelLine(string line){if(string.IsNullOrEmpty(line))return;var match=Regex.Match(line,@"https://[a-z0-9-]+\.trycloudflare\.com");if(!match.Success)return;lock(phoneGate){mobileServer.PublicHost=new Uri(match.Value).Host;phoneUrl=mobileServer.PairUrl(match.Value);phoneState="手機通道已建立，請用手機相機掃描 QR Code。";}UI(()=>{phoneStarting=false;phone.Enabled=true;phone.Text="4. 手機配對 QR Code";});}

 void StartServer(){
  bool started=false;
  for(int candidate=8765;candidate<=8785;candidate++){
   var listener=new TcpListener(IPAddress.Loopback,candidate);
   try{listener.Start();server=listener;localPort=candidate;started=true;break;}
   catch(SocketException ex){listener.Stop();if(ex.SocketErrorCode!=SocketError.AddressAlreadyInUse)throw;}
  }
  if(!started)throw new SocketException((int)SocketError.AddressAlreadyInUse);
var t=new Thread(()=>{while(!closing){try{using(var client=server.AcceptTcpClient()){client.ReceiveTimeout=2000;client.SendTimeout=2000;using(var stream=client.GetStream()){var reader=new StreamReader(stream,Encoding.ASCII,false,1024,true);string line=reader.ReadLine();int size=0;string h;while(!string.IsNullOrEmpty(h=reader.ReadLine())){size+=h.Length;if(size>8192)throw new IOException();}string body,kind,code;if(line=="GET /api/snapshot HTTP/1.1"){body=Snapshot();kind="application/json";code="200 OK";}else if(line!=null&&line.StartsWith("GET /api/history")&&line.EndsWith(" HTTP/1.1")){body=HistoryResponse(line.Split(' ')[1]);kind="application/json";code="200 OK";}else if(line=="GET /api/phone HTTP/1.1"){body=PhoneSnapshot();kind="application/json";code="200 OK";}else if(line=="GET /phone HTTP/1.1"){body=File.ReadAllText(Path.Combine("..","phone.html"),Encoding.UTF8);kind="text/html";code="200 OK";}else if(line=="GET /phone.js HTTP/1.1"||line=="GET /vendor/qrcode.js HTTP/1.1"){body=File.ReadAllText(Path.Combine("..",line.Split(' ')[1].Substring(1)),Encoding.UTF8);kind="text/javascript";code="200 OK";}else if(line=="GET /?mode=live HTTP/1.1"||line=="GET / HTTP/1.1"){body=File.ReadAllText(Path.Combine("..","index.html"),Encoding.UTF8).Replace("window.liveMode=new URLSearchParams(location.search).get(\"mode\")===\"live\";","window.liveMode=true;");kind="text/html";code="200 OK";}else if(line=="GET /large-order-alerts.js HTTP/1.1"||line=="GET /dashboard-live.js HTTP/1.1"||line=="GET /live-flow.js HTTP/1.1"||line=="GET /market-history.js HTTP/1.1"){string asset=line.Split(' ')[1].Substring(1);body=File.ReadAllText(Path.Combine("..",asset),Encoding.UTF8);kind="text/javascript";code="200 OK";}else{body="Not found";kind="text/plain";code="404 Not Found";}var bytes=Encoding.UTF8.GetBytes(body);var header=Encoding.ASCII.GetBytes("HTTP/1.1 "+code+"\r\nContent-Type: "+kind+"; charset=utf-8\r\nContent-Length: "+bytes.Length+"\r\nCache-Control: no-store\r\nConnection: close\r\nX-Content-Type-Options: nosniff\r\n\r\n");stream.Write(header,0,header.Length);stream.Write(bytes,0,bytes.Length);}}}catch(Exception){if(closing)break;}}});t.IsBackground=true;t.Start();}
}
